#ifndef STEANE_RETAINED_C33_CODE_H
#define STEANE_RETAINED_C33_CODE_H
/* Independent C algebra. SOURCE-TEXT only; no authoring-time invocation.
 * P=i^k X^x Z^z. Physical positive Hermitian P has k=pop(x&z) mod4.
 * No static scientific arrays: the caller owns every cached declaration. */
typedef struct { uint8_t x,z,k,pad; } C33P;
static unsigned c33_pop(unsigned x){unsigned n=0;for(unsigned j=0;j<7;j++){unsigned b=x&1u;n+=b;x>>=1;q_count(5,3);}return n;}
static int c33_and(int a,int b){int c=a&b;q_count(5,1);return c;}
static void c33_need(int a,unsigned cost,const char*s){q_count(5,cost);q_guard(a,s);}
static C33P c33_p(unsigned x,unsigned z,unsigned k){C33P p;p.x=(uint8_t)x;p.z=(uint8_t)z;p.k=(uint8_t)(k&3u);p.pad=0;q_count(5,4);return p;}
static C33P c33_pos(unsigned x,unsigned z){unsigned t=x&z;q_count(5,1);unsigned k=c33_pop(t)&3u;q_count(5,1);return c33_p(x,z,k);}
static C33P c33_mul(C33P a,C33P b){unsigned ax=a.x,az=a.z,ak=a.k,bx=b.x,bz=b.z,bk=b.k;q_count(5,6);unsigned x=ax^bx,z=az^bz,t=az&bx;q_count(5,3);unsigned n=c33_pop(t),k=ak+bk+(n<<1);q_count(5,3);return c33_p(x,z,k);}
static unsigned c33_anti(C33P a,C33P b){unsigned ax=a.x,az=a.z,bx=b.x,bz=b.z;q_count(5,4);unsigned t=(ax&bz)^(az&bx);q_count(5,3);unsigned v=c33_pop(t)&1u;q_count(5,1);return v;}
static unsigned c33_same(C33P a,C33P b){unsigned ax=a.x,az=a.z,bx=b.x,bz=b.z;q_count(5,4);int x=(ax==bx),z=(az==bz);q_count(5,2);int both=c33_and(x,z);unsigned same=(unsigned)both;q_count(5,1);return same;}
static C33P c33_gen(unsigned j){q_count(4,1);switch(j){case 0:return(C33P){85,0,0,0};case 1:return(C33P){102,0,0,0};case 2:return(C33P){120,0,0,0};case 3:return(C33P){0,85,0,0};case 4:return(C33P){0,102,0,0};case 5:return(C33P){0,120,0,0};case 6:return(C33P){127,0,0,0};case 7:return(C33P){0,127,0,0};case 8:return(C33P){0,1,0,0};case 9:return(C33P){0,2,0,0};default:q_guard(0,"C33 basis address");return(C33P){0,0,0,0};}}
static C33P c33_stab(unsigned m){C33P p={0,0,0,0};for(unsigned j=0;j<6;j++){unsigned b=(m>>j)&1u;q_count(5,2);if(b)p=c33_mul(p,c33_gen(j));}return p;}
static C33P c33_basis(unsigned m){unsigned x=0,z=0;for(unsigned j=0;j<10;j++){unsigned b=(m>>j)&1u;q_count(5,2);if(b){C33P p=c33_gen(j);unsigned px=p.x,pz=p.z;q_count(5,2);x^=px;z^=pz;q_count(5,2);}}return c33_pos(x,z);}
static C33P c33_logical(unsigned a){q_count(4,1);switch(a){case 0:return(C33P){0,0,0,0};case 1:return(C33P){127,0,0,0};case 2:return(C33P){127,127,1,0};case 3:return(C33P){0,127,0,0};default:q_guard(0,"C33 logical address");return(C33P){0,0,0,0};}}
static C33P c33_site(unsigned a,unsigned site){q_count(4,1);unsigned b=1u<<site;q_count(5,1);switch(a){case 0:return(C33P){0,0,0,0};case 1:return c33_p(b,0,0);case 2:return c33_p(b,b,1);case 3:return c33_p(0,b,0);default:q_guard(0,"C33 Pauli dispatch");return(C33P){0,0,0,0};}}
static unsigned c33_syndrome(C33P p){unsigned s=0;for(unsigned j=0;j<6;j++){unsigned b=c33_anti(p,c33_gen(j));s|=b<<j;q_count(5,2);}return s;}
static C33P c33_h(C33P p,unsigned site){unsigned x=p.x,z=p.z,k=p.k;q_count(5,3);unsigned bx=(x>>site)&1u,bz=(z>>site)&1u;q_count(5,4);unsigned both=bx&bz,d=bx^bz,mask=d<<site;q_count(5,3);x^=mask;z^=mask;k+=both<<1;q_count(5,4);return c33_p(x,z,k);}
static C33P c33_sback(C33P p,unsigned site){unsigned x=p.x,z=p.z,k=p.k;q_count(5,3);unsigned b=(x>>site)&1u;q_count(5,2);z^=b<<site;k-=b;q_count(5,3);return c33_p(x,z,k);}
static C33P c33_cx(C33P p,unsigned c,unsigned t){unsigned x=p.x,z=p.z,k=p.k;q_count(5,3);unsigned a=(x>>c)&1u,b=(z>>t)&1u;q_count(5,4);x^=a<<t;z^=b<<c;q_count(5,4);return c33_p(x,z,k);}
static unsigned c33_real_sign(C33P p,C33P positive){unsigned a=p.k,b=positive.k;q_count(5,2);unsigned d=(a-b)&3u;q_count(5,2);int ok=(d==0u)|(d==2u);q_count(5,3);q_guard(ok,"C33 real Hermitian phase");unsigned n=(d>>1)&1u;q_count(5,2);return n;}
static void c33_basis_inverse(uint16_t pivot[14],uint16_t word[14]){for(unsigned j=0;j<14;j++){pivot[j]=0;word[j]=0;}unsigned rank=0;for(unsigned j=0;j<10;j++){C33P p=c33_gen(j);unsigned x=p.x,z=p.z;q_count(5,2);unsigned v=x|(z<<7),m=1u<<j;q_count(5,3);for(int b=13;b>=0;b--){unsigned sh=(unsigned)b;q_count(5,1);unsigned bit=(v>>sh)&1u;q_count(5,2);if(!bit)continue;q_count(4,2);unsigned pv=pivot[b],pw=word[b];q_count(5,2);if(pv){v^=pv;m^=pw;q_count(5,2);}else{pivot[b]=(uint16_t)v;word[b]=(uint16_t)m;rank++;q_count(5,3);break;}}}c33_need(rank==10u,1,"C33 independent rank10 support");}
static unsigned c33_solve(const uint16_t pivot[14],const uint16_t word[14],C33P p,unsigned *remaining){unsigned x=p.x,z=p.z;q_count(5,2);unsigned v=x|(z<<7),m=0;q_count(5,2);for(int b=13;b>=0;b--){unsigned sh=(unsigned)b;q_count(5,1);unsigned bit=(v>>sh)&1u;q_count(5,2);if(bit){q_count(4,2);unsigned pv=pivot[b],pw=word[b];q_count(5,2);v^=pv;m^=pw;q_count(5,2);}}*remaining=v;return m;}
static unsigned c33_reduce(const uint16_t pivot[14],const uint16_t word[14],C33P p,unsigned *negative){unsigned rem=0,m=c33_solve(pivot,word,p,&rem);unsigned dirty=m>>8;q_count(5,1);int ok0=(rem==0),ok1=(dirty==0);q_count(5,2);q_guard(c33_and(ok0,ok1),"C33 normalizer reduction");unsigned x=(m>>6)&1u,z=(m>>7)&1u,sm=m&63u;q_count(5,5);unsigned a=(x^z)|(z<<1);q_count(5,3);C33P r=c33_mul(c33_stab(sm),c33_logical(a));q_guard(c33_same(r,p),"C33 signed normalizer label");*negative=c33_real_sign(p,r);return a;}
static void c33_total_D(C33P out[64]){uint64_t filled=1;out[0]=(C33P){0,0,0,0};for(unsigned j=0;j<7;j++)for(unsigned a=1;a<4;a++){C33P p=c33_site(a,j);unsigned s=c33_syndrome(p);uint64_t bit=UINT64_C(1)<<s;q_count(5,1);uint64_t old=filled&bit;q_count(5,1);if(!old){out[s]=p;filled|=bit;q_count(5,1);}}for(unsigned j=0;j<7;j++)for(unsigned k=j+1;k<7;k++)for(unsigned a=1;a<4;a++)for(unsigned b=1;b<4;b++){C33P p=c33_mul(c33_site(a,j),c33_site(b,k));unsigned s=c33_syndrome(p);uint64_t bit=UINT64_C(1)<<s;q_count(5,1);uint64_t old=filled&bit;q_count(5,1);if(!old){out[s]=p;filled|=bit;q_count(5,1);}}c33_need(filled==UINT64_MAX,1,"C33 complete support-lex D");for(unsigned s=0;s<64;s++)c33_need(c33_syndrome(out[s])==s,1,"C33 D syndrome");}
#endif
